import { createBuildEntry } from "./commonRolldown.js";
//#region src/configs/utils/createRolldownNodeConfig.ts
function createRolldownNodeConfig(props) {
	const input = props?.entry ?? ["./src/index.ts"];
	const output = props?.output ?? "dist";
	return (props?.formats ?? ["es", "cjs"]).map((format) => createBuildEntry(input, output, format));
}
//#endregion
export { createRolldownNodeConfig };
